"use client";
import { useState } from "react";
import QuoteSubmitButton from "@/Components/UI/Forms/QuoteSubmitButton";
import styles from "@/Components/UI/Forms/FormStyle.module.scss";
export default function Preview() {
  const [loading, setLoading] = useState(false);
  return <main style={{maxWidth:500,margin:"80px auto",padding:24,color:"#24382E","--hero-ink":"#1E5B43","--hero-accent":"#DCE8D2"}}>
    <button type="button" onClick={() => setLoading(!loading)} style={{padding:12,marginBottom:24}}>Toggle loading preview</button>
    <p>Homepage submit</p>
    <div className={styles.hero}><QuoteSubmitButton isLoading={loading} variant="hero" /></div>
    <p style={{marginTop:32}}>Standard quote submit</p>
    <QuoteSubmitButton isLoading={loading} />
  </main>;
}
